	label: string;
	models: PiModel[];
};

/** 팝오버 목록 한 줄. 목록은 `provider/modelId`를 그대로 보여 주고 provider로 묶는다. */
export type PiPickerItem = { value: string; group?: string };

/** Settings › Models 의 Model list 섹션: pi 카탈로그 전체와 `model-filter.json` 의 상태.
 *  `version` 은 저장할 때 그대로 돌려보내고, 그 사이 파일이 바뀌었으면 서버가 409로 거절한다. */
export type PiFilterModel = { id: string; name: string; free: boolean; listed: boolean; missing: boolean };
export type PiFilterProvider = { id: string; label: string; restricted: boolean; models: PiFilterModel[] };
export type PiFilterView = {
	enabled: boolean;
	includeFree: boolean;
	version: string;
	problem: string | null;
	providers: PiFilterProvider[];
};

export async function fetchPiFilter(signal?: AbortSignal): Promise<PiFilterView> {
	return request<PiFilterView>("/api/pi/model-filter", { signal });
}

/** `enabled` 와 `providers` 는 pi 파일에 쓰고, 빠진 provider 는 제한이 풀린다. */
export function savePiFilter(next: {
	enabled: boolean;
	providers: Record<string, string[]>;
	version: string;
}): Promise<PiFilterView> {
	return request<PiFilterView>("/api/pi/model-filter", {
		method: "PUT",
		body: JSON.stringify(next),
	});
}

/** 대시보드만의 free 포함 여부(`~/.local/state/dashboard/model-filter.json`). */
export function saveFreeModels(includeFree: boolean): Promise<PiFilterView> {
	return request<PiFilterView>("/api/pi/model-filter/free", {
		method: "PUT",
		body: JSON.stringify({ includeFree }),
	});
}

/** `/api/pi/models`: 필터가 남긴 목록과, 필터가 가렸을 뿐 아직 돌릴 수 있는 모델 id.
 *  저장된 선택이 `hidden` 에 있으면 대안으로 바꾸지 않는다(필터는 보이는 목록만 줄인다). */
export type PiCatalog = { providers: PiProvider[]; hidden: string[] };

export async function fetchPiCatalog(signal?: AbortSignal): Promise<PiCatalog> {
	const body = await request<{ providers?: PiProvider[]; hidden?: string[] }>("/api/pi/models", {
		signal,
	});
	return {
		providers: Array.isArray(body.providers) ? body.providers : [],
		hidden: Array.isArray(body.hidden) ? body.hidden : [],
	};
}

export async function fetchPiModels(signal?: AbortSignal): Promise<PiProvider[]> {
	return (await fetchPiCatalog(signal)).providers;
}

/** provider 순서대로 한 줄씩, provider 머리글을 달아서. */
export function piPickerItems(providers: PiProvider[]): PiPickerItem[] {
	return providers.flatMap((provider) =>
		provider.models.map((model) => ({
			value: model.id,
			group: provider.label,
		})),
	);
}

