 *  같은 provider 의 마지막 항목 뒤에 넣어 머리글이 두 번 서지 않게 하고, provider 자체가 사라졌으면
 *  이름을 알 수 없으니 묶음 없이 끝에 둔다. */
export function withCurrentModel(
	items: PiPickerItem[],
	providers: PiProvider[],
	current: string | undefined,
): PiPickerItem[] {
