edits.newText:
export function piEffortsFor(providers: PiProvider[], id: string): PiEffort[] {
	return findPiModel(providers, id)?.efforts ?? [...piEffortLevels];
}

/** 카탈로그에서 그 모델을 찾는다. id가 정확히 같으면 그것, 아니면 provider가 바뀐 같은 이름. */
function findPiModel(providers: PiProvider[], id: string): PiModel | undefined {
	const models = providers.flatMap((provider) => provider.models);
	const exact = models.find((model) => model.id === id);
	if (exact) return exact;
	const bare = id.slice(id.lastIndexOf("/") + 1);
	return models.find((model) => model.id === bare || model.id.endsWith(`/${bare}`));
}

/**
 * 받는 쪽(receiver)이 아는 level 중 그 모델이 허용하는 것만, Pi 순서대로. 모델이 사라졌거나
 * 겹치는 level이 하나도 없으면 받는 쪽 목록 전체를 연다(빈 드롭다운을 만들지 않는다).
 */
export function piEffortsWithin(
	providers: PiProvider[],
	id: string,
	within: readonly PiEffort[],
): PiEffort[] {
	const effort = findPiModel(providers, id);
	if (!effort) return [...within];
	const allowed = piEffortLevels.filter(
		(level) => effort.efforts.includes(level) && within.includes(level),
	);
	return allowed.length > 0 ? allowed : [...within];
}

